// --------------------------------------------------------------------------
// Comptime dispatch — three separate switches by func_index
//   func_index is the 0-based position in the function list.
//   The Zig compiler turns sequential index switches into jump tables.
//
// Usage:
//   const builtins = @import("s_engine_builtins.zig");
//   const user     = @import("my_functions.zig");
//   const D        = Dispatch(builtins, user);
//   const result   = D.main_(index, params, inst, event);
// --------------------------------------------------------------------------
pub fn Dispatch(comptime builtins: type, comptime user: type) type {
    return struct {
        pub fn main_(index: u16, params: []const Param, inst: *anyopaque, event: Event) Result {
            return switch (index) {
                0 => builtins.se_function_interface(params, inst, event),  // SE_FUNCTION_INTERFACE
                1 => builtins.se_event_dispatch(params, inst, event),  // SE_EVENT_DISPATCH
                2 => builtins.se_chain_flow(params, inst, event),  // SE_CHAIN_FLOW
                3 => builtins.se_if_then_else(params, inst, event),  // SE_IF_THEN_ELSE
                4 => builtins.se_return_pipeline_reset(params, inst, event),  // SE_RETURN_PIPELINE_RESET
                5 => builtins.se_return_pipeline_halt(params, inst, event),  // SE_RETURN_PIPELINE_HALT
                6 => builtins.se_cond(params, inst, event),  // SE_COND
                7 => builtins.se_state_machine(params, inst, event),  // SE_STATE_MACHINE
                8 => builtins.se_tick_delay(params, inst, event),  // SE_TICK_DELAY
                9 => builtins.se_fork(params, inst, event),  // SE_FORK
                10 => builtins.se_return_terminate(params, inst, event),  // SE_RETURN_TERMINATE
                else => .terminate,
            };
        }

        pub fn oneshot(index: u16, params: []const Param, inst: *anyopaque, event: Event) void {
            switch (index) {
                0 => builtins.se_set_field(params, inst, event),  // SE_SET_FIELD
                1 => builtins.se_log(params, inst, event),  // SE_LOG
                2 => user.display_event_info(params, inst, event),  // DISPLAY_EVENT_INFO
                3 => builtins.se_queue_event(params, inst, event),  // SE_QUEUE_EVENT
                else => {},
            }
        }

        pub fn pred(index: u16, params: []const Param, inst: *anyopaque, event: Event) bool {
            return switch (index) {
                0 => builtins.se_check_event(params, inst, event),  // SE_CHECK_EVENT
                1 => builtins.se_true(params, inst, event),  // SE_TRUE
                else => false,
            };
        }
    };
}

// --------------------------------------------------------------------------
// evalCall — dispatches by function kind, returns unified Result
//   Predicates return bool → mapped to continue_/halt
//   Oneshots return void  → mapped to continue_ (with done-bit guard)
//   Main returns Result   → passed through
// --------------------------------------------------------------------------
pub fn makeEvalCall(comptime D: type) type {
    return struct {
        pub fn evalCall(params: []const Param, inst: *anyopaque, event: Event) Result {
            const ref = params[1].func_ref;
            const body = params[2 .. params[0].open_call.content_count];
            return switch (ref.kind) {
                .main_, .main_pointer => D.main_(ref.func_index, body, inst, event),
                .oneshot, .oneshot_survives => blk: {
                    D.oneshot(ref.func_index, body, inst, event);
                    break :blk .continue_;
                },
                .pred, .pred_composite => blk: {
                    const ok = D.pred(ref.func_index, body, inst, event);
                    break :blk if (ok) .continue_ else .halt;
                },
            };
        }
    };
}
